package com.jnapanam.sportszone.tournament.dto;import com.jnapanam.sportszone.tournament.model.*;import java.time.Instant;import java.util.*;public record TeamResponse(UUID id,UUID tournamentId,String tournamentName,String name,UUID captainId,String captainName,TeamStatus status,List<MemberResponse>members,Instant registeredAt){public record MemberResponse(UUID id,String name,String email,String mobile){}public static TeamResponse from(TournamentTeam t,List<TournamentTeamMember>m){return new TeamResponse(t.getId(),t.getTournament().getId(),t.getTournament().getName(),t.getName(),t.getCaptain().getId(),t.getCaptain().getFullName(),t.getStatus(),m.stream().map(x->new MemberResponse(x.getId(),x.getName(),x.getEmail(),x.getMobile())).toList(),t.getRegisteredAt());}}
